import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const isContactsValid = fullName.trim() !== '' && email.includes('@');
  const isAddressValid = address.trim() !== '' && city.trim() !== '';

  const canGoNext = step === 0 ? isContactsValid : step === 1 ? isAddressValid : true;

  const goBack = () => setStep((s) => Math.max(0, s - 1));
  const goNext = () => setStep((s) => Math.min(steps.length - 1, s + 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
        padding: '24px',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(e) => setFullName(e.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            errorText={email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(e) => setCity(e.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(e) => setPostalCode(e.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные перед отправкой">
            Убедитесь, что контакты и адрес указаны верно.
          </JxAlert>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', color: 'var(--jx-text-2)' }}>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Имя:</strong> {fullName || '—'}
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Почта:</strong> {email || '—'}
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Телефон:</strong> {phone || '—'}
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Адрес:</strong> {address || '—'}
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Город:</strong> {city || '—'}
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Индекс:</strong> {postalCode || '—'}
            </span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext} disabled={!canGoNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

